#!/usr/bin/env bash
set -euo pipefail
test "$(mysql --skip-ssl --connect-timeout=3 -h127.0.0.1 -P6033 -uroot -pstroppy_mysql -Dstroppy -Nse 'SELECT 1')" = 1 && test "$(mysql --ssl --ssl-verify-server-cert=0 --connect-timeout=3 -h${ip:db-1} -uroot -pstroppy_mysql -Nse "SELECT COUNT(*) >= 3 AND SUM(MEMBER_STATE='ONLINE')=COUNT(*) FROM performance_schema.replication_group_members")" = 1 && test "$(mysql --ssl --ssl-verify-server-cert=0 --connect-timeout=3 -h${ip:db-replica-1} -uroot -pstroppy_mysql -Nse "SELECT COUNT(*) >= 3 AND SUM(MEMBER_STATE='ONLINE')=COUNT(*) FROM performance_schema.replication_group_members")" = 1 && test "$(mysql --ssl --ssl-verify-server-cert=0 --connect-timeout=3 -h${ip:db-replica-2} -uroot -pstroppy_mysql -Nse "SELECT COUNT(*) >= 3 AND SUM(MEMBER_STATE='ONLINE')=COUNT(*) FROM performance_schema.replication_group_members")" = 1
